function avatarHTML(big=false){const a=S.prefs.avatar||'mascot-01',cls='av'+(big?' big':'');if(/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(a))return `<span class='${cls} photo'><img src='${a}' alt='Avatar profil'></span>`;if(a==='initials')return `<span class='${cls} initials'>${e(((S.prefs.name||'?').trim()[0]||'?').toUpperCase())}</span>`;if(MASCOTS.includes(a))return `<span class='${cls} mascot'><img src='/mascots/${a}.svg' alt='Maskot Taktiva'></span>`;if(OLD_AVATARS.includes(a))return `<span class='${cls} emoji' role='img' aria-label='Avatar profil'>${e(a)}</span>`;return `<span class='${cls} mascot'><img src='/mascots/mascot-01.svg' alt='Maskot Taktiva'></span>`}
function setAvatar(i){S.prefs.avatar=i<0?'initials':(MASCOTS[i]||'mascot-01');render()}
function avatarUpload(input){const file=input.files&&input.files[0];if(!file)return;const allowed=['image/jpeg','image/png','image/webp'];if(!allowed.includes(file.type)){alert(T('Format foto tidak didukung. Gunakan JPG, PNG, atau WebP.','Unsupported photo format. Use JPG, PNG, or WebP.'));input.value='';return}if(file.size>8*1024*1024){alert(T('Ukuran foto maksimal 8 MB.','Photo must be 8 MB or smaller.'));input.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{try{const side=Math.min(img.naturalWidth,img.naturalHeight);if(!side)throw new Error('invalid image');const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const ctx=canvas.getContext('2d');ctx.drawImage(img,(img.naturalWidth-side)/2,(img.naturalHeight-side)/2,side,side,0,0,256,256);S.prefs.avatar=canvas.toDataURL('image/jpeg',0.76);render()}catch(x){alert(T('Foto tidak bisa diproses. Coba foto lain.','Could not process this photo. Try another image.'))}};img.onerror=()=>alert(T('Foto tidak bisa dibuka. Coba foto lain.','Could not open this photo. Try another image.'));img.src=reader.result};reader.onerror=()=>alert(T('Foto gagal dibaca.','Could not read the photo.'));reader.readAsDataURL(file);input.value=''}
