function tr(s){if(L!='en')return s;const k=s.trim();if(k in EX)return s.replace(k,EX[k]);let r=s;for(const[a,b]of RX)r=r.replace(a,b);return r}
function applyLang(){document.documentElement.lang=L;const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentNode.closest('script,style')?2:1});let n;while(n=w.nextNode()){if(n.__o===undefined)n.__o=n.data;const v=tr(n.__o);if(n.data!==v)n.data=v}
document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(a=>{if(!el.hasAttribute(a))return;const k='o_'+a.replace('-','_');if(el.dataset[k]===undefined)el.dataset[k]=el.getAttribute(a);el.setAttribute(a,tr(el.dataset[k]))}));
document.querySelectorAll('.lg').forEach(b=>b.textContent=L.toUpperCase())}
function setLang(){L=L=='id'?'en':'id';try{localStorage.setItem('taskmate.lang',L)}catch(x){}if(em)render();else applyLang()}
