function glow(){if(!matchMedia('(hover:hover)').matches)return;let q=0;addEventListener('pointermove',e=>{if(q)return;q=requestAnimationFrame(()=>{q=0;const s=document.documentElement.style;s.setProperty('--mx',e.clientX+'px');s.setProperty('--my',e.clientY+'px')})})}
