if(!S.tasks.find(t=>t.id==sel))sel=(A[0]?A[0].t:S.tasks[0]).id;const t=S.tasks.find(x=>x.id==sel),cap=+S.prefs.hours||1;
const ST=[['Riset & kumpulkan referensi',.2],['Susun outline',.1],['Tulis draf utama',.4],['Revisi & periksa ulang',.2],['Finalisasi & kumpulkan',.1]];let end=add(t.due,-S.prefs.buffer),cum=0;const rows=[];
