function openTask(id){editId=id||null;const t=S.tasks.find(x=>x.id==id)||{title:'',course:'',due:add(TODAY,7),est:4,imp:2};$('#dt').textContent=id?'Ubah tugas':'Tugas baru';f_t.value=t.title;f_c.value=t.course;f_d.value=t.due;f_e.value=t.est;f_i.value=t.imp;paintImp();f_k.innerHTML=typeOpts();f_k.value=t.type||'';applyLang();dlg.showModal()}
function saveTask(){if(!f_t.value.trim()||!f_d.value){alert('Isi judul tugas dan deadline.');return}const o={title:f_t.value.trim(),course:f_c.value.trim(),due:f_d.value,est:Math.max(.5,+f_e.value||1),imp:+f_i.value,type:f_k.value};
if(editId){const t=S.tasks.find(t=>t.id==editId);if(t.plan&&o.type!=(t.type||''))delete t.plan;else if(t.plan)scale(t,o.est);Object.assign(t,o)}else S.tasks.push({id:uid(),progress:0,...o});dlg.close();render();toast(T('Tugas disimpan. Kepentingan: ','Task saved. Importance: ')+[,T('Rendah','Low'),T('Sedang','Medium'),T('Tinggi','High')][o.imp])}
function setP(id,v){S.tasks.find(t=>t.id==id).progress=v;render()}
function del(id){if(confirm('Hapus tugas ini?')){S.tasks=S.tasks.filter(t=>t.id!=id);render()}}
function mon(n){cm=new Date(cm.getFullYear(),cm.getMonth()+n,1);render()}
function pf(k,v){S.prefs[k]=v;save()}
function exp(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({prefs:S.prefs,tasks:S.tasks},null,1)],{type:'application/json'}));a.download='taktiva_backup.json';a.click()}
function imp(i){const f=i.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!Array.isArray(d.tasks))throw 0;S.prefs={...S.prefs,...d.prefs};S.tasks=d.tasks;S.id=Math.max(10,...d.tasks.map(t=>+t.id||0));render()}catch(x){alert('File tidak valid. Gunakan file taktiva_backup.json.')}};r.readAsText(f)}
