const kind=t=>{if(t.type&&TY[t.type])return t.type;const s=(t.title+' '+t.course).toLowerCase();return/ppt|presentasi|slide/.test(s)?'ppt':/makalah|paper|laporan|jurnal/.test(s)?'makalah':/essay|esai/.test(s)?'essay':/poster|infografis/.test(s)?'poster':/video|film|vlog/.test(s)?'video':/web|prototype|aplikasi/.test(s)?'web':/uts|uas|ujian|quiz|kuis|exam|ulangan/.test(s)?'ujian':'lain'};
