const pSel=v=>{sel=+v;render()},pName=(i,v)=>pAct(p=>{p[i].n=v.trim()||p[i].n}),pH=(i,v)=>pAct(p=>{p[i].h=Math.max(.5,+v||.5)}),pDone=i=>pAct(p=>{p[i].d=!p[i].d}),pDel=i=>pAct(p=>{if(p.length>1)p.splice(i,1)}),pAdd=()=>pAct(p=>{p.push({n:T('Tahap baru','New stage'),h:1,d:false})}),pMove=(i,d)=>pAct(p=>{const j=i+d;if(j>=0&&j<p.length)[p[i],p[j]]=[p[j],p[i]]});
