const toast=m=>{const d=document.createElement('div');d.className='toast';d.textContent=m;document.body.appendChild(d);setTimeout(()=>d.remove(),2800)};
function pCap2(v){S.prefs.hours=v;render();toast(T(`Kapasitas belajar jadi ${v} jam/hari. Risiko sudah dihitung ulang.`,`Study capacity set to ${v} h/day. Risks recalculated.`))}
