function paintSy(){const s=$('#sy');if(!s)return;s.className='sy '+syncSt;s.textContent={ok:T('Tersinkron','Synced'),sync:T('Menyinkronkan…','Syncing…'),off:T('Offline, disimpan di perangkat','Offline, saved on device'),local:T('Mode lokal','Local mode')}[syncSt];s.title=cloud?T('Klik untuk sinkronkan sekarang','Click to sync now'):T('Data hanya tersimpan di perangkat ini','Data stays on this device only')}
function setSt(x){syncSt=x;paintSy()}
function resnap(){snap={};S.tasks.forEach(t=>{snap[t.id]=JSON.stringify({...t,u:0})});snap.p=JSON.stringify(S.prefs)}
function stamp(){const n=Date.now(),cur={};S.del=S.del||{};S.tasks.forEach(t=>{const j=JSON.stringify({...t,u:0});cur[t.id]=j;if(snap[t.id]!==j)t.u=n});Object.keys(snap).forEach(i=>{if(i!='p'&&!(i in cur))S.del[i]=n});const pj=JSON.stringify(S.prefs);if(snap.p!==pj)S.pu=n;snap=cur;snap.p=pj}
function merge(R){const D={...(R.del||{})};Object.entries(S.del||{}).forEach(([k,v])=>{D[k]=Math.max(v,D[k]||0)});const M={};[...(R.tasks||[]),...S.tasks].forEach(t=>{const o=M[t.id];if(!o||(t.u||0)>(o.u||0))M[t.id]=t});S.tasks=Object.values(M).filter(t=>!(D[t.id]>(t.u||0))).sort((a,b)=>a.id-b.id);S.del=D;if((R.pu||0)>(S.pu||0)){S.prefs={...S.prefs,...R.prefs};S.pu=R.pu}resnap()}
const queue=()=>{clearTimeout(pend);pend=setTimeout(push,1200)},dirtyNow=()=>{stamp();return JSON.stringify(S)!==lastJ};
async function push(){if(!cloud||!tok||busy)return false;busy=true;setSt('sync');let ok=false;try{for(let i=0;i<3;i++){stamp();const sent=JSON.stringify(S),r=await api('data',{method:'PUT',body:`{"data":${sent},"rev":${rev}}`});if(r.s==200){rev=r.j.rev;lastJ=sent;try{localStorage.setItem(RV+em,rev)}catch(x){}ok=true;break}if(r.s==409){merge(r.j.data);rev=r.j.rev;merged=true;continue}if(r.s==401){busy=false;expire();return false}break}}finally{busy=false}
setSt(ok?'ok':'off');if(merged){merged=false;render()}else if(ok&&JSON.stringify(S)!==lastJ)queue();return ok}
async function pull(){if(!cloud||!tok||busy||dlg.open||!$('#auth').hidden)return;const el=document.activeElement;if(el&&/INPUT|TEXTAREA|SELECT/.test(el.tagName))return;const r=await api('data');if(r.s==401)return expire();if(r.s!=200||!r.j.data||r.j.rev<=rev)return;if(dirtyNow())merge(r.j.data);else{S=r.j.data;resnap();lastJ=JSON.stringify(S)}rev=r.j.rev;try{localStorage.setItem(RV+em,rev)}catch(x){}render();toast(T('Data diperbarui dari perangkat lain.','Updated from another device.'))}
function save(){if(cloud&&tok)stamp();try{localStorage.setItem(K,JSON.stringify(S))}catch(x){}if(cloud&&tok&&JSON.stringify(S)!==lastJ){setSt(navigator.onLine?'sync':'off');queue()}else paintSy()}
function authUI(r){reg=r;$('#rg').hidden=!r;$('#rg2').hidden=!(r&&cloud);a_p.autocomplete=r?'new-password':'current-password';$('#t_in').className='btn s'+(r?' g':'');$('#t_up').className='btn s'+(r?'':' g');$('#a_b').textContent=r?'Buat akun':'Masuk';$('#a_m').textContent='';applyLang()}
function startApp(){view='dash';sel=null;const v=$('#v');v.classList.add('an');setTimeout(()=>v.classList.remove('an'),800);document.body.classList.remove('ld');$('#auth').hidden=true;$('.app').hidden=false;render()}
function start(m){em=m;K='taskmate.data.'+m;load();startApp()}
function showAuth(){em='';tok='';document.body.classList.remove('ld');$('.app').hidden=true;$('#auth').hidden=false;authUI(false);tgi()}
function expire(sl){clearTimeout(pend);try{localStorage.removeItem(SK);localStorage.removeItem(TKN)}catch(x){}showAuth();if(!sl)$('#a_m').textContent=T('Sesi berakhir. Silakan masuk lagi.','Your session expired. Please sign in again.')}
async function logout(){if(cloud&&tok){while(busy)await new Promise(r=>setTimeout(r,200));if(dirtyNow()){setSt('sync');const ok=await push();if(!ok&&!confirm(T('Ada perubahan yang belum tersinkron. Tetap keluar? Perubahan itu akan hilang.','Some changes are not synced yet. Sign out anyway? Those changes will be lost.')))return}try{localStorage.removeItem(K);localStorage.removeItem(RV+em)}catch(x){}}
clearTimeout(pend);try{localStorage.removeItem(SK);localStorage.removeItem(TKN)}catch(x){}showAuth()}
const authGo=()=>cloud?cloudAuth():doAuth();
async function enter(m,u){em=m;K='taskmate.data.'+m;const d=await api('data');if(d.s==401)return expire();
if(d.s==200&&d.j.data){S=d.j.data;rev=d.j.rev;lastJ=JSON.stringify(S);resnap();setSt('ok')}else{rev=0;lastJ='';snap={};load(false);if(!S.prefs.name||S.prefs.name=='Mahasiswa')S.prefs.name=u.name;S.prefs.level=S.prefs.level||u.level;setSt('sync')}
try{localStorage.setItem(RV+m,rev)}catch(x){}startApp()}
async function cloudAuth(){const m=a_e.value.trim().toLowerCase(),p=a_p.value,msg=x=>{$('#a_m').textContent=x},b=$('#a_b');
if(!/^[^ @]+@[^ @]+[.][^ @]+$/.test(m))return msg(T('Masukkan email yang valid.','Enter a valid email.'));if(p.length<8)return msg(T('Kata sandi minimal 8 karakter.','Password must be at least 8 characters.'));
if(reg){if(!a_n.value.trim())return msg(T('Isi nama lengkapmu.','Enter your full name.'));if(p!==a_c.value)return msg(T('Konfirmasi kata sandi tidak sama.','Passwords do not match.'))}
b.disabled=true;const old=b.textContent;b.textContent=T('Memproses…','Please wait…');
const r=await api(reg?'register':'login',{method:'POST',body:JSON.stringify({email:m,password:p,name:a_n.value.trim(),level:a_l.value})});b.disabled=false;b.textContent=old;
if(r.s==0)return msg(T('Tidak bisa terhubung ke server. Periksa koneksimu.','Cannot reach the server. Check your connection.'));
if(r.s==409)return msg(T('Email sudah terdaftar. Silakan masuk.','This email is already registered. Please sign in.'));
if(r.s==401)return msg(T('Email atau kata sandi salah.','Incorrect email or password.'));
if(r.s==429)return msg(T('Terlalu banyak percobaan. Coba lagi dalam 10 menit.','Too many attempts. Try again in 10 minutes.'));
if(r.s!=200)return msg(T('Terjadi masalah di server. Coba lagi.','Server problem. Please try again.'));
tok=r.j.token;try{localStorage.setItem(TKN,tok);localStorage.setItem(SK,m)}catch(x){}a_p.value=a_c.value='';await enter(m,r.j.user)}
async function boot(){document.body.classList.add('ld');glow();try{const t=localStorage.getItem(TK);if(t)document.documentElement.dataset.theme=t}catch(x){}
const pg=await api('ping',{},3000);cloud=pg.s==200&&!!pg.j.ok;let s='',t='';try{s=localStorage.getItem(SK);t=localStorage.getItem(TKN)}catch(x){}
if(cloud){if(s&&t){tok=t;em=s;K='taskmate.data.'+s;try{rev=+localStorage.getItem(RV+s)||0}catch(x){}const d=await api('data');
if(d.s==401)expire(true);else{if(d.s==200&&d.j.data){S=d.j.data;rev=d.j.rev;lastJ=JSON.stringify(S);resnap();setSt('ok')}else{load();setSt(d.s==0?'off':'sync')}startApp()}}else showAuth()}
else if(s&&users()[s])start(s);else showAuth();
[a_p,a_c].forEach(x=>x.addEventListener('keydown',ev=>{if(ev.key=='Enter')authGo()}));
setInterval(pull,25000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pull()});addEventListener('online',push);addEventListener('offline',()=>setSt('off'));
addEventListener('pagehide',()=>{if(cloud&&tok&&em&&$('#auth').hidden){stamp();const s=JSON.stringify(S);if(s!==lastJ)fetch('/api/data',{method:'PUT',keepalive:true,headers:{'content-type':'application/json',authorization:'Bearer '+tok},body:`{"data":${s},"rev":${rev}}`})}})}
const paintImp=()=>document.querySelectorAll('#f_ib button').forEach((b,i)=>{b.className='btn s '+(+f_i.value==i+1?'':'g')}),setImp=n=>{f_i.value=n;paintImp()},impTag=t=>{const n=+t.imp||2;return `<span class='ip i${n}'>${'★'.repeat(n)} ${T('Kepentingan','Importance')} ${[,T('Rendah','Low'),T('Sedang','Medium'),T('Tinggi','High')][n]}</span>`};
boot();
